-- 恢复 coa_client_spell_description 的法术描述中文
-- 背景：该表的内容会作为客户端 Spell.dbc 的描述覆盖下发。库内 4456 条是英文原文，
-- 把客户端 Spell.dbc 里本来已有的中文描述盖掉了，玩家看到的技能说明因此是英文。
-- 本次分两部分：一是 25 条客户端 DBC 里也没中文的，人工补译；
-- 二是 4431 条客户端 DBC 第 176 列（zhCN）已有中文的，按原文回填。
-- 只改 Description 文本，不动 ID、ToolTip，也不删任何行。
-- By leewheel 2026年11月26日

